Simulationseinstellungen:

viewof tMax_PID = Range([1, 10e3], {
  value: 10,
  transform: Math.log,
  label: tex`t_{max}`
})

y_PID = {
  const output_PID = [];

  let p_PID; 
  let t0_PID = -0.5;
  //let tMax_PID = 20;

  let t_PID = t0_PID;
  let d_PID = 0;
  let u_PID = 0;
  let i_PID = 0;
  let e_PID = 0;
  let eprev_PID = e_PID;
  let pu_PID = u_PID;
  let ppu_PID = u_PID;
  let du_PID = 0;
  let ddu_PID = 0;
  let pdu_PID = 0;
  let y_PID = 0;
  let py_PID = 0;
  let ppy_PID = 0;
  let dy_PID = 0;
  let ddy_PID = 0;
  let pdy_PID = 0;
  let de_PID = 0;
  let dt_PID = 0.001;
  let s_PID = setPoint_PID(t0_PID);
  output_PID.push({ t_PID, u_PID, s_PID });

  let j_PID = 1;
  while (t_PID &lt; tMax_PID) {
    t_PID = t0_PID + j_PID * dt_PID;

    s_PID = setPoint_PID(t_PID);

    e_PID = s_PID - u_PID;
    de_PID = e_PID-eprev_PID;

    //du = (u-pu)/dt;
    //ddu = (du - pdu)/dt;

    //dy = (py - y)/dt;
    //ddy = (dy - pdy)/dt;

    p_PID = e_PID;
    i_PID += e_PID * dt_PID;
    d_PID = de_PID/dt_PID;

    y_PID = (Kp_PID * p_PID + Ki_PID * i_PID + Kd_PID * d_PID);

    u_PID = (2*D_PID*T_PID*dt_PID*pu_PID + Kpt2_PID*dt_PID**2*y_PID - T_PID**2*ppu_PID + 2*T_PID**2*pu_PID)/(2*D_PID*T_PID*dt_PID + T_PID**2 + dt_PID**2);

    ppu_PID = pu_PID;
    pu_PID = u_PID;
    //pdu = du;

    //ppy = py;
    //py = y;
    //pdy = dy;

    eprev_PID = e_PID;

    output_PID.push({ t_PID, u_PID, s_PID, e_PID, y_PID });
    j_PID++;
  }

  return output_PID;
}

setPoint_PID = {
  function hardstep_PID(x) {
    return Math.max(0, Math.min(1, x));
  }
  function smoothstep_PID(x) {
    var x = hardstep_PID(x);
    return x * x * (3 - 2 * x);
  }
  switch (input_PID) {
    case 'step':
      return t_PID =&gt; (t_PID &gt;= 0 ? 1 : 0);
    case 'ramp':
      return t_PID =&gt; (t_PID &gt;= 0 ? t_PID : 0);
    case 'quadratic ramp':
      return t_PID =&gt; (t_PID &gt;= 0 ? t_PID * t_PID : 0);
    case 'smoothstep':
      return smoothstep_PID;
    case 'hardstep':
      return hardstep_PID;
    default:
      throw new Error('Invalid input');
  }
}
